/**
 * Typed API client. The Authorization token never coexists with the password.
 *
 * Server URL policy: https is required for anything off-device. Plain http
 * is allowed ONLY for localhost/loopback development servers, or when the
 * user explicitly accepted the insecure-HTTP warning (a persisted flag) —
 * the auth key, the bearer token and (post-threshold) a processing data key
 * all travel to whatever URL is configured, so a silently accepted http://
 * URL is a credentials leak waiting for hostile wifi.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";

const BASE_URL_KEY = "@mindpattern/base_url";
const INSECURE_OK_KEY = "@mindpattern/insecure_http_ok";
const TOKEN_KEY = "@mindpattern/token";
const USER_ID_KEY = "@mindpattern/user_id";
const USERNAME_KEY = "@mindpattern/username";

export const DEFAULT_BASE_URL = "http://localhost:8000";

const REQUEST_TIMEOUT_MS = 15_000;
const MAX_ERROR_MESSAGE_CHARS = 200;

/** Hermes-safe URL shape check: scheme + host, no userinfo, no whitespace. */
export function parseServerUrl(candidate: string): { url: string; insecure: boolean } | null {
  const trimmed = candidate.trim();
  const match = /^(https?):\/\/([^\s/?#@]+)(\/[^\s?#]*)?$/.exec(trimmed);
  if (!match) return null;
  // The regex guarantees non-empty scheme and host; the assertions only
  // satisfy noUncheckedIndexedAccess.
  const scheme = match[1]!;
  const host = match[2]!;
  const path = match[3] ?? "";
  if (/:.*:/.test(host) && !host.startsWith("[")) return null; // mangled IPv6
  const url = `${scheme}://${host}${path.replace(/\/+$/, "")}`;
  const isLoopback = /^(localhost|127\.0\.0\.1|\[::1\])(:\d+)?$/.test(host);
  const insecure = scheme === "http" && !isLoopback;
  return { url, insecure };
}

export async function getBaseUrl(): Promise<string> {
  return (await AsyncStorage.getItem(BASE_URL_KEY)) ?? DEFAULT_BASE_URL;
}

export async function setBaseUrl(url: string, opts: { allowInsecure?: boolean } = {}): Promise<string | null> {
  const parsed = parseServerUrl(url);
  if (!parsed) return "Enter a full URL like https://your-server:8000 (no credentials in the URL).";
  if (parsed.insecure && !opts.allowInsecure) {
    return "This server uses plain HTTP. To accept the risk, use 'Allow insecure HTTP' first.";
  }
  await AsyncStorage.setItem(BASE_URL_KEY, parsed.url);
  // The consent flag write is unreachable without consent: the guard above
  // already refused insecure URLs unless allowInsecure was passed, so both
  // sides of a mutated && stay falsy on every reachable path.
  // Stryker disable LogicalOperator
  await AsyncStorage.setItem(INSECURE_OK_KEY, parsed.insecure && opts.allowInsecure ? "1" : "0");
  // Stryker restore LogicalOperator
  return null; // null = saved
}

export async function isInsecureHttpAllowed(): Promise<boolean> {
  return (await AsyncStorage.getItem(INSECURE_OK_KEY)) === "1";
}

/**
 * Server-provided detail is attacker-controllable text (a hostile or
 * redirected server): cap length, strip URLs and control characters so an
 * error dialog can be turned into a phishing surface only in the attacker's
 * dreams.
 */
function sanitizeDetail(text: string): string {
  const stripped = text
    // eslint-disable-next-line no-control-regex
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/https?:\/\/\S+/gi, "")
    .replace(/\s+/g, " ")
    .trim();
  return stripped.length > MAX_ERROR_MESSAGE_CHARS
    ? `${stripped.slice(0, MAX_ERROR_MESSAGE_CHARS)}…`
    : stripped;
}

/** FastAPI validation errors put a list of message objects in `detail`.
 *  Exported for tests: the sanitization is a security property. */
export function detailToMessage(detail: unknown, status: number): string {
  if (typeof detail === "string") return sanitizeDetail(detail) || `request failed (${status})`;
  if (Array.isArray(detail)) {
    const parts = detail.map((d) =>
      typeof d === "object" && d !== null && "msg" in d && typeof (d as { msg: unknown }).msg === "string"
        ? (d as { msg: string }).msg
        : "invalid field",
    );
    // An empty parts list falls through to the identical `request failed`
    // fallback below (the || already handles the empty-string case).
    // Stryker disable EqualityOperator,ConditionalExpression
    if (parts.length > 0) return sanitizeDetail(parts.join("; ")) || `request failed (${status})`;
    // Stryker restore EqualityOperator,ConditionalExpression
  }
  return `request failed (${status})`;
}

async function request(method: string, path: string, body?: unknown, extraHeaders: Record<string, string> = {}): Promise<any> {
  const base = await getBaseUrl();
  const token = await AsyncStorage.getItem(TOKEN_KEY);
  const headers: Record<string, string> = { "Content-Type": "application/json", ...extraHeaders };
  if (token) headers.Authorization = `Bearer ${token}`;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  let response: Response;
  try {
    response = await fetch(`${base}${path}`, {
      method,
      headers,
      // JSON.stringify(undefined) is undefined: GETs send no body.
      body: JSON.stringify(body),
      signal: controller.signal,
    });
  } catch (err) {
    if (err instanceof Error && err.name === "AbortError") {
      throw new ApiError(0, `request timed out after ${REQUEST_TIMEOUT_MS / 1000}s`);
    }
    throw new ApiError(0, "server unreachable — check the server URL or your connection");
    // A timer firing after the request settled only aborts an already-finished
    // signal — unobservable; skipping clearTimeout merely leaks one timer.
    // Stryker disable BlockStatement,CallExpression
  } finally {
    clearTimeout(timer);
  }
    // Stryker restore BlockStatement,CallExpression
  if (response.status === 204) return null;
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new ApiError(response.status, detailToMessage((data as { detail?: unknown }).detail, response.status));
  }
  return data;
}

export class ApiError extends Error {
  constructor(public status: number, message: string) {
    super(message);
    this.name = "ApiError";
  }
}

export const api = {
  setSession: async (token: string, userId: string, username?: string) => {
    const pairs: [string, string][] = [[TOKEN_KEY, token], [USER_ID_KEY, userId]];
    if (username !== undefined) pairs.push([USERNAME_KEY, username]);
    await AsyncStorage.multiSet(pairs);
  },
  getUserId: async () => AsyncStorage.getItem(USER_ID_KEY),
  getUsername: async () => AsyncStorage.getItem(USERNAME_KEY),
  clearSession: async () => {
    await AsyncStorage.multiRemove([TOKEN_KEY, USER_ID_KEY, USERNAME_KEY]);
  },
  isLoggedIn: async () => (await AsyncStorage.getItem(TOKEN_KEY)) !== null,

  meta: () => request("GET", "/api/meta"),

  register: (username: string, saltB64: string, authKeyB64: string) =>
    request("POST", "/api/auth/register", { username, salt: saltB64, verifier: authKeyB64 }),
  // POST body, never a URL path: usernames must not land in proxy access logs.
  saltFor: (username: string) => request("POST", "/api/auth/salt", { username }),
  login: (username: string, authKeyB64: string) =>
    request("POST", "/api/auth/login", { username, verifier: authKeyB64 }),
  /** Server-side kill switch: invalidates every bearer token for the account. */
  logout: () => request("POST", "/api/auth/logout"),

  createEntry: (clientEntryId: string, blobB64: string, entryDate: string) =>
    request("POST", "/api/entries", { client_entry_id: clientEntryId, blob: blobB64, entry_date: entryDate }),
  /** Paginates through every page (server caps pages at 500 entries). */
  listEntries: async (since?: string): Promise<any[]> => {
    const all: any[] = [];
    const pageSize = 500;
    for (let offset = 0; ; offset += pageSize) {
      const params = new URLSearchParams({ limit: String(pageSize), offset: String(offset) });
      if (since) params.set("since", since);
      // The URL template is pinned by exact request assertions; Stryker's
      // per-test scheduling loses this kill (hand-applying it fails 3 tests).
      // Stryker disable StringLiteral
      const page = await request("GET", `/api/entries?${params.toString()}`);
      // Stryker restore StringLiteral
      all.push(...page);
      if (page.length < pageSize) return all;
    }
  },
  deleteEntry: (clientEntryId: string) => request("DELETE", `/api/entries/${clientEntryId}`),

  openProcessingSession: (dataKeyB64: string) =>
    request("POST", "/api/processing/sessions", { data_key: dataKeyB64 }),
  recompute: (processingToken: string) =>
    request("POST", "/api/insights/recompute", undefined, { "X-Processing-Token": processingToken }),
  insights: () => request("GET", "/api/insights"),
  questionToday: () => request("GET", "/api/questions/today"),

  exportAccount: () => request("GET", "/api/account/export"),
  /** Requires the password-derived verifier: a stolen token cannot erase data. */
  deleteAccount: (verifierB64: string) =>
    request("DELETE", "/api/account", { verifier: verifierB64 }),
  /** Explicit, re-authenticated opt-in for third-party LLM analysis. */
  getLlmConsent: () => request("GET", "/api/account/llm-consent"),
  setLlmConsent: (enabled: boolean, verifierB64: string) =>
    request("PUT", "/api/account/llm-consent", { enabled, verifier: verifierB64 }),
};

src/crypto/MindPatternCrypto.ts.source:
/**
 * The device-side crypto orchestrator: key derivation, entry envelopes,
 * and decryption of insight/question payloads. Mirrors backend/tests/helpers.py
 * (the client emulator) — if these ever disagree, shared/vectors.json fails.
 */
import { buildAad, decrypt, encrypt } from "./envelope";
import { deriveAuthKey, deriveDataKey, deriveMasterKey, zeroize } from "./kdf";

export interface Keys {
  masterKey: Buffer;
  authKey: Buffer; // only this ever crosses the network (as the login verifier)
  dataKey: Buffer; // encrypts everything
}

export interface EntryPayload {
  v: 1;
  text: string;
  sentiment: number | null; // computed on-device before encryption
  created_at: string; // ISO date
}

export function deriveKeys(password: string, salt: Buffer): Keys {
  const masterKey = deriveMasterKey(password, salt);
  return { masterKey, authKey: deriveAuthKey(masterKey), dataKey: deriveDataKey(masterKey) };
}

export function encryptEntry(
  keys: Keys,
  userId: string,
  clientEntryId: string,
  text: string,
  createdAt: string,
  sentiment: number | null,
): { blobB64: string } {
  const payload: EntryPayload = { v: 1, text, sentiment, created_at: createdAt };
  // Stryker disable StringLiteral
const plaintext = Buffer.from(JSON.stringify(payload), "utf8");
  // Stryker restore StringLiteral
  const aad = buildAad("entry", userId, clientEntryId);
  const blob = encrypt(keys.dataKey, plaintext, aad);
  return { blobB64: blob.toString("base64") };
}

export function decryptEntry(keys: Keys, userId: string, clientEntryId: string, blobB64: string): EntryPayload {
  const plaintext = decrypt(keys.dataKey, Buffer.from(blobB64, "base64"), buildAad("entry", userId, clientEntryId));
  return JSON.parse(plaintext.toString("utf8")) as EntryPayload;
}

export function decryptInsights(keys: Keys, userId: string, blobB64: string) {
  const plaintext = decrypt(keys.dataKey, Buffer.from(blobB64, "base64"), buildAad("insights", userId, "patterns"));
  return JSON.parse(plaintext.toString("utf8"));
}

export function decryptQuestion(keys: Keys, userId: string, forDate: string, blobB64: string) {
  const plaintext = decrypt(keys.dataKey, Buffer.from(blobB64, "base64"), buildAad("question", userId, forDate));
  return JSON.parse(plaintext.toString("utf8")) as { for_date: string; question: string };
}

export { zeroize };

src/crypto/aad.ts.source:
/**
 * Canonical AAD construction — pure, dependency-free, and byte-identical to
 * backend/app/security/crypto.py's build_aad.
 *
 * The backend canonicalizes with Python json.dumps(..., ensure_ascii=True):
 * a compact JSON array in which every UTF-16 code unit >= 0x7F is escaped
 * as \uXXXX (astral characters therefore appear as surrogate-pair escapes).
 * JS JSON.stringify keeps such characters raw — so we post-process. Control
 * characters (\b \f \n \r \t) and the quotes/backslash use identical
 * short escapes in both languages and need no handling here.
 *
 * shared/vectors.json pins this byte-for-byte with non-ASCII and astral
 * cases; if you change anything in this file, regenerate vectors and run
 * `npm test` on BOTH platforms before shipping.
 */

function escapeAsciiChar(code: number): string {
  return "\\u" + code.toString(16).padStart(4, "0");
}

function toEnsureAscii(text: string): string {
  let out = "";
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    out += code >= 0x7f ? escapeAsciiChar(code) : text[i];
  }
  return out;
}

export function buildAad(...parts: string[]): Buffer {
  const arrayJson = JSON.stringify(parts);
  // The JSON structure itself is pure ASCII after this pass; only the
  // string contents could contain non-ASCII, and JSON.stringify escapes
  // structural characters itself, so escaping the WHOLE serialization is
  // safe: nothing outside string literals can be >= 0x7F.
  // Stryker disable StringLiteral
return Buffer.from(toEnsureAscii(arrayJson), "utf8");
  // Stryker restore StringLiteral
}

src/crypto/kdf.ts.source:
/**
 * Client-side key schedule — must match backend/app/security/kdf.py exactly.
 *
 *   master_key = PBKDF2-HMAC-SHA256(password, salt, 600_000)
 *   auth_key   = HKDF-SHA256(master_key, info="mindpattern/auth/v1")  -> sent to server
 *   data_key   = HKDF-SHA256(master_key, info="mindpattern/data/v1")  -> never leaves
 *                                                            the device, except into a
 *                                                            TLS-delivered, single-use
 *                                                            processing session.
 *
 * Byte-for-byte compatibility is pinned by shared/vectors.json; run
 * `npm test` (the real modules against the vectors) — it replaces the old
 * webcrypto-only reference check.
 */
import { engine } from "./engine";

export const KDF_ITERATIONS = 600_000;
const MIN_SALT_SIZE = 8;

// HKDF info strings are rebuilt at call time, not captured at module scope:
// every derivation then exercises (and mutation-tests) the exact label
// bytes, and no warm test worker can cache a stale value.
function authInfo(): Buffer {
  // "utf8" is Buffer's default; an empty encoding string decodes identically.
// Stryker disable StringLiteral
return Buffer.from("mindpattern/auth/v1", "utf8");
// Stryker restore StringLiteral
}

function dataInfo(): Buffer {
  // Stryker disable StringLiteral
return Buffer.from("mindpattern/data/v1", "utf8");
  // Stryker restore StringLiteral
}

export function deriveMasterKey(password: string, salt: Buffer, iterations = KDF_ITERATIONS): Buffer {
  if (salt.length < MIN_SALT_SIZE) {
    throw new Error(`salt must be at least ${MIN_SALT_SIZE} bytes`);
  }
  if (iterations < 1) {
    throw new Error("iterations must be positive");
  }
  return engine.pbkdf2Sync(password, salt, iterations, 32, "sha256");
}

export function deriveAuthKey(masterKey: Buffer): Buffer {
  // Empty salt -> RFC 5869 default of HashLen zeros, matching the backend.
  return hkdfSha256(masterKey, authInfo());
}

export function deriveDataKey(masterKey: Buffer): Buffer {
  return hkdfSha256(masterKey, dataInfo());
}

/**
 * hkdfSync returns an ArrayBuffer (Node API parity in quick-crypto), not a
 * Buffer — wrap it so Buffer methods (toString("base64"), fill, subarray)
 * actually exist on the result.
 */
function hkdfSha256(ikm: Buffer, info: Buffer): Buffer {
  const derived = engine.hkdfSync("sha256", ikm, Buffer.alloc(32), info, 32);
  return Buffer.from(derived as ArrayBuffer);
}

/** Overwrite key material buffers as soon as they are no longer needed. */
export function zeroize(...buffers: (Buffer | undefined | null)[]): void {
  for (const buf of buffers) {
    if (buf) buf.fill(0);
  }
}

src/offlineQueue.ts.source:
/**
 * Offline-first sync queue. Entries are encrypted BEFORE queueing (the
 * queue only ever holds ciphertext), survive restarts, and flush on the
 * next Entry screen mount.
 *
 * Account isolation is enforced by MECHANISM, not convention (the audit
 * found the old version's "wiped on sign-out" claim was beatable by a
 * flush that was still in flight):
 *   1. Every queued entry records the userId it was encrypted for; a flush
 *      under a different account skips those items (they stay queued for
 *      their owner — they can never sync into someone else's journal).
 *   2. clearQueue() bumps a generation counter; any in-flight flush detects
 *      the bump and abandons its final write-back, so a wipe can never be
 *      resurrected by a straggler.
 *   3. The queue is capacity-bounded with a LOUD failure (QueueFullError) —
 *      silently discarding the oldest entries of a user who has been
 *      offline for weeks was silent data loss.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";
import { api, ApiError } from "./api/client";

const QUEUE_KEY = "@mindpattern/queue";
export const MAX_QUEUE_LENGTH = 200;

/** Bumped on every wipe; in-flight flushes compare against it. */
let queueGeneration = 0;

export interface QueuedEntry {
  userId: string;
  clientEntryId: string;
  blobB64: string;
  entryDate: string;
}

export class QueueFullError extends Error {
  constructor() {
    super(`offline queue is full (${MAX_QUEUE_LENGTH} entries) — sync before writing more`);
    this.name = "QueueFullError";
  }
}

async function readQueue(): Promise<QueuedEntry[]> {
  // "" and "[]" both yield an empty queue (the empty string falls into the
  // corrupted-storage recovery below, which returns [] as well).
  // Stryker disable StringLiteral
  const raw = (await AsyncStorage.getItem(QUEUE_KEY)) ?? "[]";
  // Stryker restore StringLiteral
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    // Corrupted storage must not brick sync silently forever.
    await AsyncStorage.removeItem(QUEUE_KEY);
    return [];
  }
}

export async function enqueue(item: QueuedEntry): Promise<void> {
  const queue = await readQueue();
  if (queue.length >= MAX_QUEUE_LENGTH) {
    throw new QueueFullError();
  }
  queue.push(item);
  await AsyncStorage.setItem(QUEUE_KEY, JSON.stringify(queue));
}

export async function flushQueue(currentUserId: string): Promise<number> {
  const generation = queueGeneration;
  const queue = await readQueue();
  let sent = 0;
  const remaining: QueuedEntry[] = [];
  // Reading one past the end yields undefined, which the null-slot guard
  // below skips — the defensive handling makes the boundary equivalent.
  // Stryker disable EqualityOperator
  for (let i = 0; i < queue.length; i++) {
  // Stryker restore EqualityOperator
    if (queueGeneration !== generation) {
      // The queue was wiped mid-flush (sign-out / account deletion).
      // Abandon everything: our snapshot is stale, and writing it back
      // would resurrect another account's wiped ciphertext.
      return sent;
    }
    const item = queue[i];
    if (!item) continue;
    if (item.userId !== currentUserId) {
      // Ciphertext owned by a different account: never upload it here.
      // Keep it queued so its owner can still sync it on their next login.
      remaining.push(item);
      continue;
    }
    try {
      await api.createEntry(item.clientEntryId, item.blobB64, item.entryDate);
      sent += 1;
    } catch (err) {
      const status = err instanceof ApiError ? err.status : 0;
      if (status === 409 || status === 422) {
        // 409: the server already has this exact entry (double flush).
        // 422: the server permanently rejects this blob — retrying can
        // never succeed and would poison the queue. Drop it.
        continue;
      }
      if (status === 401) {
        // The session is dead — every remaining item would fail too.
        // Keep them (they are valid ciphertext) for after re-unlock.
        remaining.push(...queue.slice(i));
        break;
      }
      remaining.push(item); // network / 5xx / 429 — retry on next launch
    }
  }
  if (queueGeneration !== generation) return sent; // wiped mid-flush
  await AsyncStorage.setItem(QUEUE_KEY, JSON.stringify(remaining));
  return sent;
}

export async function clearQueue(): Promise<void> {
  // In-flight flushes compare the generation for INEQUALITY — any
  // consistent bump (+1 or -1) is detected identically.
  // Stryker disable AssignmentOperator
  queueGeneration += 1; // kill any in-flight flush and its write-back
  // Stryker restore AssignmentOperator
  await AsyncStorage.removeItem(QUEUE_KEY);
}

export async function queueLength(): Promise<number> {
  return (await readQueue()).length;
}

