/**
 * engine.ts loader branches, imported lazily inside each test so that a
 * mutant breaking module initialization fails the TEST (a collection-level
 * failure is invisible to mutation runners' kill accounting).
 */
import { describe, expect, it } from "vitest";
import nodeCrypto from "node:crypto";

describe("crypto engine loader", () => {
  it("module-level engine resolves a working backend via require()", async () => {
    const { engine } = await import("../src/crypto/engine");
    // vite-node's require + the quickCryptoMock alias -> node:crypto.
    expect(engine.randomBytes(4)).toHaveLength(4);
    expect(engine.pbkdf2Sync("pw", Buffer.alloc(8), 1, 32, "sha256")).toHaveLength(32);
  });

  it("prefers react-native-quick-crypto when the resolver provides it", async () => {
    const { loadEngine } = await import("../src/crypto/engine");
    const sentinel = { randomBytes: () => Buffer.alloc(0) } as never;
    const req = (id: string) => (id === "react-native-quick-crypto" ? sentinel : nodeCrypto);
    expect(loadEngine(req)).toBe(sentinel);
  });

  it("falls back to node:crypto when quick-crypto cannot load", async () => {
    const { loadEngine } = await import("../src/crypto/engine");
    const req = (id: string) => {
      if (id === "react-native-quick-crypto") throw new Error("native addon unavailable");
      if (id === "node:crypto") return nodeCrypto;
      throw new Error(`unexpected require: ${id}`);
    };
    const resolved = loadEngine(req);
    expect(Buffer.from(resolved.hkdfSync("sha256", Buffer.alloc(32, 1), Buffer.alloc(32), Buffer.alloc(0), 32) as ArrayBuffer)).toHaveLength(32);

    const cipher = resolved.createCipheriv("aes-256-gcm", Buffer.alloc(32, 2), Buffer.alloc(12, 3));
    cipher.setAAD(Buffer.from("aad"));
    const ct = Buffer.concat([cipher.update(Buffer.from("m")), cipher.final()]);
    expect(ct.length).toBe(1);
    expect(cipher.getAuthTag()).toHaveLength(16);
  });

  it("fails loudly when no require() exists at all", async () => {
    const { loadEngine } = await import("../src/crypto/engine");
    // In an ESM-only host the bare `require` reference throws
    // ReferenceError at module load — loud on purpose.
    const req = () => {
      throw new ReferenceError("require is not defined");
    };
    expect(() => loadEngine(req)).toThrow(ReferenceError);
  });
});

tests/offlineQueue.test.ts.source:
/**
 * Offline queue security regressions (from the red-team audit):
 *  - one account's queued ciphertext can never be uploaded under another
 *    account's session,
 *  - a wipe during an in-flight flush is never resurrected by the flush's
 *    write-back,
 *  - capacity is a loud failure, never silent destruction of oldest items.
 */
import { beforeEach, describe, expect, it, vi } from "vitest";
import storage from "./helpers/storageMock";

vi.mock("../src/api/client", () => {
  class ApiError extends Error {
    constructor(public status: number, message: string) {
      super(message);
    }
  }
  return {
    ApiError,
    api: {
      // Controlled per-test via the exposed mock functions.
      createEntry: vi.fn(async () => ({})),
    },
  };
});

// eslint-disable-next-line @typescript-eslint/no-var-requires
const { api, ApiError } = await import("../src/api/client") as any;
// eslint-disable-next-line @typescript-eslint/no-var-requires
const { enqueue, flushQueue, clearQueue, queueLength, MAX_QUEUE_LENGTH, QueueFullError } =
  await import("../src/offlineQueue");

const aliceEntry = (n: number) => ({
  userId: "alice",
  clientEntryId: `a-${n}`,
  blobB64: Buffer.alloc(40, n).toString("base64"),
  entryDate: "2026-09-01",
});

beforeEach(() => {
  storage.__reset();
  vi.mocked(api.createEntry).mockClear();
  vi.mocked(api.createEntry).mockImplementation(async () => ({}));
});

describe("account isolation", () => {
  it("never uploads another account's queued entries", async () => {
    await enqueue(aliceEntry(1));
    await enqueue({ ...aliceEntry(2), userId: "bob" });

    const sent = await flushQueue("alice");

    expect(sent).toBe(1);
    expect(api.createEntry).toHaveBeenCalledTimes(1);
    expect(api.createEntry).toHaveBeenCalledWith("a-1", aliceEntry(1).blobB64, "2026-09-01");

    // Bob's ciphertext stays queued for Bob — not uploaded, not dropped.
    expect(await queueLength()).toBe(1);
    const bobStillQueued = await flushQueue("bob");
    expect(bobStillQueued).toBe(1);
    expect(await queueLength()).toBe(0);
  });
});

describe("wipe races", () => {
  it("abandons the write-back when the queue is cleared mid-flush", async () => {
    await enqueue(aliceEntry(1));
    await enqueue(aliceEntry(2));

    let calls = 0;
    vi.mocked(api.createEntry).mockImplementation(async () => {
      calls += 1;
      if (calls === 1) {
        // Sign-out happens while the flush is between items.
        await clearQueue();
      }
      return {};
    });

    const sent = await flushQueue("alice");
    expect(sent).toBe(1); // first item went out before the wipe
    // The wipe must win: the flush may not re-persist its stale snapshot —
    // the key is GONE, not merely emptied.
    expect(await storage.getItem("@mindpattern/queue")).toBeNull();
    expect(await queueLength()).toBe(0);
  });

  it("skips the final write-back when the wipe lands after the last upload", async () => {
    await enqueue(aliceEntry(1));
    vi.mocked(api.createEntry).mockImplementation(async () => {
      await clearQueue(); // wipes after the upload succeeded
      return {};
    });

    const sent = await flushQueue("alice");
    expect(sent).toBe(1);
    expect(await storage.getItem("@mindpattern/queue")).toBeNull(); // never resurrected
    expect(await queueLength()).toBe(0);
  });
});

describe("failure handling", () => {
  it("keeps items on network errors and drops them on permanent 4xx", async () => {
    await enqueue(aliceEntry(1)); // will 422 -> dropped
    await enqueue(aliceEntry(2)); // will 5xx -> kept for retry
    vi.mocked(api.createEntry).mockImplementation(async (id: string) => {
      if (id === "a-1") throw new ApiError(422, "bad blob");
      throw new ApiError(0, "server unreachable");
    });

    const sent = await flushQueue("alice");
    expect(sent).toBe(0);
    const remaining = JSON.parse((await storage.getItem("@mindpattern/queue")) ?? "[]");
    expect(remaining.map((r: any) => r.clientEntryId)).toEqual(["a-2"]);
  });

  it("stops uploading on 401 and keeps the rest for after re-unlock", async () => {
    await enqueue(aliceEntry(1));
    await enqueue(aliceEntry(2));
    vi.mocked(api.createEntry).mockImplementation(async () => {
      throw new ApiError(401, "invalid token");
    });

    await flushQueue("alice");
    const remaining = JSON.parse((await storage.getItem("@mindpattern/queue")) ?? "[]");
    expect(remaining).toHaveLength(2);
  });

  it("on 401 mid-queue keeps every unsent item and stops retrying", async () => {
    await enqueue(aliceEntry(1)); // succeeds
    await enqueue(aliceEntry(2)); // 401
    await enqueue(aliceEntry(3)); // never attempted
    let calls = 0;
    vi.mocked(api.createEntry).mockImplementation(async (id: string) => {
      calls += 1;
      if (id === "a-2") throw new ApiError(401, "invalid token");
      return {};
    });

    const sent = await flushQueue("alice");
    expect(sent).toBe(1);
    expect(calls).toBe(2); // item 3 was never attempted
    const remaining = JSON.parse((await storage.getItem("@mindpattern/queue")) ?? "[]");
    expect(remaining.map((r: any) => r.clientEntryId)).toEqual(["a-2", "a-3"]);
  });

  it("fails LOUDLY at capacity instead of silently discarding old entries", async () => {
    for (let i = 0; i < MAX_QUEUE_LENGTH; i++) {
      await enqueue(aliceEntry(i));
    }
    await expect(enqueue(aliceEntry(999))).rejects.toBeInstanceOf(QueueFullError);
    await expect(enqueue(aliceEntry(999))).rejects.toThrow(
      `offline queue is full (${MAX_QUEUE_LENGTH} entries) — sync before writing more`,
    );
    const err = new QueueFullError();
    expect(err.name).toBe("QueueFullError");
    // And the existing entries are intact.
    expect(await queueLength()).toBe(MAX_QUEUE_LENGTH);
  });

  it("keeps uploading after a plain network error (unlike 401)", async () => {
    await enqueue(aliceEntry(1)); // network error -> retried later, loop continues
    await enqueue(aliceEntry(2)); // succeeds
    vi.mocked(api.createEntry).mockImplementation(async (id: string) => {
      if (id === "a-1") throw new TypeError("fetch failed");
      return {};
    });
    const sent = await flushQueue("alice");
    expect(sent).toBe(1); // item 2 went out after item 1's network error
    const remaining = JSON.parse((await storage.getItem("@mindpattern/queue")) ?? "[]");
    expect(remaining.map((r: any) => r.clientEntryId)).toEqual(["a-1"]);
  });

  it("drops entries the server already has (409 double-flush)", async () => {
    await enqueue(aliceEntry(1));
    vi.mocked(api.createEntry).mockImplementation(async () => {
      throw new ApiError(409, "entry already exists");
    });
    const sent = await flushQueue("alice");
    expect(sent).toBe(0);
    expect(await queueLength()).toBe(0);
  });

  it("keeps entries on non-ApiError failures (treated like network errors)", async () => {
    await enqueue(aliceEntry(1));
    vi.mocked(api.createEntry).mockImplementation(async () => {
      throw new TypeError("fetch failed");
    });
    await flushQueue("alice");
    expect(await queueLength()).toBe(1);
  });
});

describe("corrupted storage recovery", () => {
  it("clears unparseable queue data instead of bricking sync forever", async () => {
    await storage.setItem("@mindpattern/queue", "{not json");
    expect(await queueLength()).toBe(0);
    expect(await storage.getItem("@mindpattern/queue")).toBeNull();
  });

  it("treats non-array queue data as empty (and keeps it for repair)", async () => {
    await storage.setItem("@mindpattern/queue", "42");
    expect(await queueLength()).toBe(0);
    expect(await storage.getItem("@mindpattern/queue")).toBe("42");
  });

  it("skips null slots instead of crashing the flush", async () => {
    await storage.setItem("@mindpattern/queue", JSON.stringify([null, aliceEntry(1)]));
    const sent = await flushQueue("alice");
    expect(sent).toBe(1);
    const remaining = JSON.parse((await storage.getItem("@mindpattern/queue")) ?? "[]");
    expect(remaining).toHaveLength(0);
  });
});

tests/client.test.ts.source:
/**
 * API client hardening regressions: server-URL policy (the remote enabler
 * of credential interception) and error-detail sanitization (a hostile
 * server must not phish through our own dialogs).
 */
import { describe, expect, it } from "vitest";

import { parseServerUrl, detailToMessage } from "../src/api/client";

describe("parseServerUrl", () => {
  it("accepts https servers and normalizes trailing slashes", () => {
    expect(parseServerUrl("https://api.example.com/")).toEqual({
      url: "https://api.example.com",
      insecure: false,
    });
    expect(parseServerUrl("https://api.example.com:8443/v1/")).toEqual({
      url: "https://api.example.com:8443/v1",
      insecure: false,
    });
    // Multiple trailing slashes collapse; inner path segments are kept.
    expect(parseServerUrl("https://api.example.com/v1///")).toEqual({
      url: "https://api.example.com/v1",
      insecure: false,
    });
    // Whitespace around the input is trimmed.
    expect(parseServerUrl("  https://api.example.com  ")).toEqual({
      url: "https://api.example.com",
      insecure: false,
    });
  });

  it("allows plain http only for loopback development servers", () => {
    expect(parseServerUrl("http://localhost:8000")!.insecure).toBe(false);
    expect(parseServerUrl("http://127.0.0.1:8000")!.insecure).toBe(false);
    expect(parseServerUrl("http://[::1]:8000")!.insecure).toBe(false);
  });

  it("requires the scheme at the very start (anchored match)", () => {
    expect(parseServerUrl("xxhttps://api.example.com")).toBeNull();
    expect(parseServerUrl("https://api.example.com junk")).toBeNull();
  });

  it("rejects any unbracketed host with multiple colons, however spaced", () => {
    // The two-colon detector must catch wide gaps too, not just :x:.
    expect(parseServerUrl("http://ab:cd:ef:8000")).toBeNull();
    expect(parseServerUrl("http://1:2::3:8000")).toBeNull();
  });

  it("flags non-loopback http as insecure", () => {
    const parsed = parseServerUrl("http://nas.lan:8000");
    expect(parsed?.insecure).toBe(true);
    expect(parsed?.url).toBe("http://nas.lan:8000");
  });

  it("rejects credential-stuffed, malformed and non-HTTP URLs", () => {
    expect(parseServerUrl("https://user:pass@evil.example")).toBeNull();
    expect(parseServerUrl("ftp://example.com")).toBeNull();
    expect(parseServerUrl("not a url")).toBeNull();
    expect(parseServerUrl("https://")).toBeNull();
    expect(parseServerUrl("https://ho st")).toBeNull();
    // Mangled IPv6 (two colons, unbracketed) must not slip through.
    expect(parseServerUrl("http://1:2::3:8000")).toBeNull();
  });

  it("flags bracketed non-loopback IPv6 http as insecure", () => {
    expect(parseServerUrl("http://[2001:db8::1]:8000")).toEqual({
      url: "http://[2001:db8::1]:8000",
      insecure: true,
    });
  });

  it("requires a lowercase scheme and rejects userinfo, queries and fragments", () => {
    expect(parseServerUrl("HTTP://api.example.com")).toBeNull(); // scheme is case-pinned
    expect(parseServerUrl("https://api.example.com?x=1")).toBeNull(); // query strings rejected
    expect(parseServerUrl("https://api.example.com#frag")).toBeNull(); // fragments rejected
    expect(parseServerUrl("https://user@api.example.com")).toBeNull();
    expect(parseServerUrl("https://user:pass@api.example.com")).toBeNull();
  });

  it("classifies loopback hosts exactly (with and without ports)", () => {
    for (const host of ["localhost", "127.0.0.1", "[::1]"]) {
      expect(parseServerUrl(`http://${host}:8000`)).toEqual({
        url: `http://${host}:8000`,
        insecure: false,
      });
      expect(parseServerUrl(`http://${host}`)).toEqual({
        url: `http://${host}`,
        insecure: false,
      });
    }
    // Look-alikes must NOT be treated as loopback.
    for (const host of ["localhost.evil.com", "127.0.0.2", "[::2]", "mylocalhost"]) {
      expect(parseServerUrl(`http://${host}`)?.insecure).toBe(true);
    }
  });
});

describe("detailToMessage sanitization", () => {
  it("strips whole URLs so error dialogs cannot phish", () => {
    expect(
      detailToMessage("Your account was compromised — visit https://evil.example/fix now", 400),
    ).toBe("Your account was compromised — visit now");
    // Every URL in a multi-URL message is removed entirely.
    expect(detailToMessage("go http://a.io/x and https://b.io/y now", 400)).toBe("go and now");
  });

  it("trims surrounding whitespace after control-character replacement", () => {
    expect(detailToMessage("  spaced out  ", 400)).toBe("spaced out");
  });

  it("caps hostile message length", () => {
    const message = detailToMessage("A".repeat(5_000), 400);
    expect(message.length).toBeLessThanOrEqual(202);
  });

  it("strips control characters", () => {
    const message = detailToMessage("bad\u0000\u0007blob", 422);
    expect(message).toBe("bad blob");
  });

  it("handles FastAPI validation lists and falls back to a status message", () => {
    expect(detailToMessage([{ loc: ["body"], msg: "field required" }], 422)).toBe("field required");
    expect(detailToMessage(undefined, 500)).toBe("request failed (500)");
    expect(detailToMessage({ odd: true }, 500)).toBe("request failed (500)");
  });

  it("joins multiple validation messages with '; '", () => {
    expect(
      detailToMessage([{ msg: "first problem" }, { msg: "second problem" }], 422),
    ).toBe("first problem; second problem");
  });

  it("maps malformed validation entries to a generic field message", () => {
    expect(detailToMessage([{ msg: 123 }], 422)).toBe("invalid field"); // non-string msg
    expect(detailToMessage([null], 422)).toBe("invalid field"); // null entry
    expect(detailToMessage(["raw string"], 422)).toBe("invalid field"); // not an object
  });

  it("falls back to the status message for empty details", () => {
    expect(detailToMessage([], 422)).toBe("request failed (422)");
    expect(detailToMessage("", 400)).toBe("request failed (400)"); // empty string detail
    expect(detailToMessage([{ msg: "" }], 422)).toBe("request failed (422)"); // sanitized to empty
  });

  it("keeps messages at exactly the cap and truncates one char over", () => {
    const exactly = "x".repeat(200);
    expect(detailToMessage(exactly, 400)).toBe(exactly);
    const over = detailToMessage("x".repeat(201), 400);
    expect(over).toHaveLength(201); // 200 chars + 1-char ellipsis
    expect(over.endsWith("…")).toBe(true);
  });
});

tests/vault.test.ts.source:
/**
 * Vault lifecycle: memory-only key custody, zeroization on rotation and
 * lock, locked-access failure, and observer notification semantics.
 */
import { beforeEach, describe, expect, it, vi } from "vitest";

import { vault } from "../src/vault";

const keysOf = (fill: number) => ({
  masterKey: Buffer.alloc(32, fill),
  authKey: Buffer.alloc(32, fill + 1),
  dataKey: Buffer.alloc(32, fill + 2),
});

beforeEach(() => {
  vault.lock(); // reset to a known locked state; also drops stale listeners? (it does not — see below)
});

describe("vault", () => {
  it("starts locked: get() throws and isUnlocked() is false", () => {
    expect(vault.isUnlocked()).toBe(false);
    expect(() => vault.get()).toThrow("vault is locked");
  });

  it("unlock stores keys and notifies subscribers; get() returns them", () => {
    const listener = vi.fn();
    const unsubscribe = vault.subscribe(listener);
    const keys = keysOf(1);
    vault.unlock(keys);
    expect(vault.isUnlocked()).toBe(true);
    expect(vault.get()).toBe(keys);
    expect(listener).toHaveBeenCalledTimes(1);

    // The master key is zeroized on hand-off: only auth/data remain useful.
    expect(keys.masterKey.equals(Buffer.alloc(32))).toBe(true);
    expect(keys.authKey.equals(Buffer.alloc(32, 2))).toBe(true);

    unsubscribe();
  });

  it("re-unlocking zeroizes the previous session's keys first", () => {
    const first = keysOf(10);
    vault.unlock(first);
    vault.unlock(keysOf(20));
    expect(first.authKey.equals(Buffer.alloc(32))).toBe(true);
    expect(first.dataKey.equals(Buffer.alloc(32))).toBe(true);
    expect(vault.get().authKey.equals(Buffer.alloc(32, 21))).toBe(true);
  });

  it("lock zeroizes the current keys, clears state and notifies", () => {
    const keys = keysOf(30);
    vault.unlock(keys);
    const listener = vi.fn();
    vault.subscribe(listener);
    vault.lock();
    expect(vault.isUnlocked()).toBe(false);
    expect(keys.authKey.equals(Buffer.alloc(32))).toBe(true);
    expect(keys.dataKey.equals(Buffer.alloc(32))).toBe(true);
    expect(listener).toHaveBeenCalledTimes(1);
    expect(() => vault.get()).toThrow("vault is locked");
  });

  it("lock() on an already-locked vault is a safe no-op that still notifies", () => {
    const listener = vi.fn();
    vault.subscribe(listener);
    vault.lock();
    expect(listener).toHaveBeenCalledTimes(1);
  });

  it("unsubscribe stops further notifications", () => {
    const listener = vi.fn();
    const unsubscribe = vault.subscribe(listener);
    vault.unlock(keysOf(40));
    unsubscribe();
    vault.lock();
    expect(listener).toHaveBeenCalledTimes(1);
  });

  it("notifies every subscribed listener", () => {
    const a = vi.fn();
    const b = vi.fn();
    vault.subscribe(a);
    const offB = vault.subscribe(b);
    vault.unlock(keysOf(50));
    offB();
    vault.lock();
    expect(a).toHaveBeenCalledTimes(2);
    expect(b).toHaveBeenCalledTimes(1);
  });
});
